const previous = input.state.found ? input.state.data : {seen_ids: []};
const response = input.response;
const ok = response.status_code >= 200 && response.status_code < 300;
if (ok && (!response.data || response.data.success === false || !Array.isArray(response.data.posts))) {
  throw new Error("Expected a JSON feed with a posts array");
}
const seen = previous.seen_ids;
const posts = ok ? response.data.posts.filter(p => p && typeof p.id === "string" && !seen.includes(p.id) && !p.is_deleted && !p.is_spam).slice(0, 5).map(p => ({
  id: p.id, title: String(p.title || "").slice(0, 300), content: String(p.content || "").slice(0, 2000)
})) : [];
return {
  generate: posts.length > 0,
  idle: posts.length === 0,
  posts,
  ids: posts.map(p => p.id),
  state: {
    seen_ids: seen,
    last_http_status: response.status_code,
    retry_after: response.headers["retry-after"] || "",
    outcome: ok ? "no_new_posts" : "http_error"
  }
};

const state = input.prepared.state;
return {
  text: JSON.stringify({source_ids: input.prepared.ids, proposal: input.proposal, published: false}, null, 2),
  state: {
    seen_ids: [...new Set([...state.seen_ids, ...input.prepared.ids])].slice(-200),
    last_http_status: state.last_http_status,
    retry_after: state.retry_after,
    outcome: "draft_saved"
  }
};
